/**
 * Глава X «Сектор Махарий», стр. 249–303.
 *
 * Headings keep their English slug — see src/compendium/journal-anchors.json.
 * У сорока четырёх страниц почти одинаковая скорлупа: «Важные персоны…»
 * (`personalities-of-…`), «Власть имущие…» (`the-powers-of-…`) и «Слухи»
 * (`whispers`). На `X5EFP7IgIUx6CaBW#rogue-traders-of-note` ссылается
 * «Империум», на `#the-macharian-conquests` — «Реквизиция».
 *
 * Названия по книге: Киферида, Дримор, Исс, Андоск, туманность Галлоск;
 * Айзинитская бездна, Древняя гармония, Эйтлер, Витезович, Волл, Омир,
 * Бельншудха.
 *
 * Слаги «Власть имущих» у C7 гуляют: где-то `the-powers-of-…`, где-то
 * `powers-of-…`, а у Тен Джи-Марна — `powers-of-arrians-wrath`. Каждый взят
 * дословно с английской страницы.
 *
 * Расхождения русского издания, которые сюда не перенесены:
 *  • стр. 270 — врезка Дао Тейраса названа «Идеи для приключений», хотя у C7
 *    это обычный `whispers`; здесь, как и везде, «Слухи». У Иллисира заголовок
 *    и правда `adventure-hook`, там оставлено «Идеи для приключений».
 *  • стр. 269 «Йосия фон Фолхабер» против стр. 270 «Иосия»; взят первый.
 */

export const label = "Журналы (Основная книга)";

const U = (uuid, label) => `@UUID[${uuid}]{${label}}`;
const h = (level, slug, text) => `<h${level} id="${slug}">${text}</h${level}>`;
const p = (...parts) => `<p>${parts.join("")}</p>`;
const title = text => `<p class="like-h2">${text}</p>`;
/** «Система: …» — шапка планетной статьи. */
const system = name => p(`<strong>Система</strong>: ${name}`);
/** Заголовок «Слухи» — h5, как у C7. */
const whispers = () => h(5, "whispers", "Слухи");

/* ── Сектор Махарий (вводная), стр. 249 ─────────────────────────────────*/
const sectorPage =
  `<div class="journal-image float-right flip"><img src="modules/impmal-core/assets/images/ch9.webp" height="660" /></div>` +
  p("На галактическом западе от Терры, в сегментуме Пацификус, лежит сектор Махарий — ",
    "густонаселённый край со множеством развитых миров, названный в честь одного из величайших ",
    "полководцев в имперской истории, лорда-соляра Махария. Завоевания легендарного Махария были ",
    "столь велики, что сектор, носящий его имя, вмещает лишь часть покорённых им миров. Больше пяти ",
    "сотен лет Махарий процветал, пока на галактику не опустилась Ноктис Этерна. Когда открылся ",
    "Великий разлом, многие миры по всему Империуму превратились в бледные тени самих себя — так ",
    "прошли Дни слепоты.") +
  p("Сейчас Дни слепоты закончились. Правитель сектора Ол Сеян пытается восстановить свои ",
    "разорённые владения, но крамола и беззаконие расползлись слишком широко. Многие противятся ",
    "управителю, преследуя собственные интересы, или пытаются обернуть его усилия себе на благо. ",
    "Там, где некогда ослепительно ярко воссиял свет лорда-соляра Махария, теперь сгустились самые ",
    "мрачные тени, и ни один провидец не скажет, какая участь ждёт осаждённый врагами сектор.");

