    "обыденна, а сама работа — тяжкое испытание, которое приходится выносить до самой смерти. ",
    "Никто не жалуется, ведь никто не знает другой жизни, как её не знали прошлые поколения. ",
    "Большинство гордится своим трудом на благо Империума, ибо Имперская вера учит, что Император ",
    "считает их работу священным бременем. Многие рабочие места занимают целые династии, а ",
